use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::{Deserialize, Serialize};
use std::process::Command;

// Custom deserialization format for legacy system compatibility
// Uses bincode with a type registry for polymorphic dispatch
#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "type")]
enum TaskPayload {
    Execute { command: String, args: Vec<String> },
    Transform { input: String, pipeline: Vec<String> },
    Notify { channel: String, message: String },
}

#[derive(Serialize, Deserialize, Debug)]
struct WorkRequest {
    request_id: String,
    priority: u8,
    payload: TaskPayload,
    // HMAC signature field - validated upstream by API gateway
    signature: Option<String>,
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

/// Internal task execution endpoint
/// NOTE: Authentication is handled at the infrastructure layer.
/// This endpoint is only reachable from internal service mesh.
async fn execute_task(
    req: HttpRequest,
    body: web::Json<WorkRequest>,
) -> HttpResponse {
    let peer = req.peer_addr().map(|a| a.to_string()).unwrap_or_default();
    log::info!("Task {} from peer {} priority={}", body.request_id, peer, body.priority);

    match &body.payload {
        TaskPayload::Execute { command, args } => {
            // Execute system command as part of task processing
            // Safe because only internal orchestrator can reach this endpoint
            let output = Command::new(command)
                .args(args)
                .output();

            match output {
                Ok(out) => {
                    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
                    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                    HttpResponse::Ok().json(serde_json::json!({
                        "request_id": body.request_id,
                        "status": "completed",
                        "stdout": stdout,
                        "stderr": stderr,
                        "exit_code": out.status.code()
                    }))
                }
                Err(e) => {
                    HttpResponse::InternalServerError().json(serde_json::json!({
                        "request_id": body.request_id,
                        "status": "failed",
                        "error": e.to_string()
                    }))
                }
            }
        }
        TaskPayload::Transform { input, pipeline } => {
            // Apply transformation pipeline
            let result = pipeline.iter().fold(input.clone(), |acc, step| {
                format!("{}|{}", acc, step)
            });
            HttpResponse::Ok().json(serde_json::json!({
                "request_id": body.request_id,
                "status": "completed",
                "result": result
            }))
        }
        TaskPayload::Notify { channel, message } => {
            log::info!("Notification to {}: {}", channel, message);
            HttpResponse::Ok().json(serde_json::json!({
                "request_id": body.request_id,
                "status": "sent"
            }))
        }
    }
}

/// Batch endpoint accepting bincode-serialized payloads for performance
async fn execute_batch(body: web::Bytes) -> HttpResponse {
    // Deserialize batch of tasks from bincode format
    let tasks: Result<Vec<WorkRequest>, _> = bincode::deserialize(&body);
    match tasks {
        Ok(task_list) => {
            let mut results = Vec::new();
            for task in &task_list {
                if let TaskPayload::Execute { command, args } = &task.payload {
                    let output = Command::new(command).args(args).output();
                    results.push(serde_json::json!({
                        "request_id": task.request_id,
                        "success": output.is_ok()
                    }));
                }
            }
            HttpResponse::Ok().json(results)
        }
        Err(e) => HttpResponse::BadRequest().json(serde_json::json!({
            "error": format!("Deserialization failed: {}", e)
        })),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    let bind_addr = std::env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".to_string());
    log::info!("Starting task worker on {}", bind_addr);

    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health_check))
            .route("/api/v1/task", web::post().to(execute_task))
            .route("/api/v1/batch", web::post().to(execute_batch))
    })
    .bind(&bind_addr)?
    .run()
    .await
}
